func TestSystemUserList_NoToken_MustNotLeakCftToken(t *testing.T) {
	db := setupDBUserPage(t)
	if err := db.Exec("DELETE FROM `user`").Error; err != nil {
		t.Fatalf("clean user: %v", err)
	}
	if err := db.Create(&model.User{ID: "admin", Name: "Administrator", Email: "admin@trueone.io", Enable: model.BitBool(true), Deleted: model.BitBool(false), CftToken: "SECRET-CFT-TOKEN", CreatedAt: 1700000000000}).Error; err != nil {
		t.Fatalf("seed admin: %v", err)
	}

	r := router.SetupRouter()
	req := httptest.NewRequest(http.MethodGet, "/system/user", nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)

	var got struct {
		Code int `json:"code"`
		Data []struct {
			ID       string `json:"id"`
			CftToken string `json:"cftToken"`
		} `json:"data"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &got); err != nil {
		t.Fatalf("unmarshal: %v body=%s", err, w.Body.String())
	}
	if w.Code != http.StatusUnauthorized || got.Code != 100401 {
		t.Fatalf("anonymous GET /system/user must be 401/100401, got http=%d code=%d body=%s", w.Code, got.Code, w.Body.String())
	}
	if len(got.Data) != 0 {
		t.Fatalf("anonymous response leaked %d user row(s), first id=%q cftToken=%q", len(got.Data), got.Data[0].ID, got.Data[0].CftToken)
	}
}

