func TestGlobalPermissionUpdate_MustPersistForRoleIDContract(t *testing.T) {
	db := setupDBGlobalPerm(t)
	if err := db.Exec("DELETE FROM user_role_permission").Error; err != nil {
		t.Fatalf("clean permission: %v", err)
	}

	r := router.SetupRouter()
	req := httptest.NewRequest(http.MethodPost, "/user/role/global/permission/update", strings.NewReader(`{"roleId":"member","permissions":[{"id":"CASE:WRITE","enable":true}]}`))
