	if err := db.Model(&model.UserRolePermission{}).Where("role_id = ?", "").Count(&orphan).Error; err != nil {
		t.Fatalf("count orphan: %v", err)
	}
	if orphan != 0 {
		t.Fatalf("update returned success but wrote %d row(s) with empty role_id (roleId/userRoleId 字段名不匹配)", orphan)
	}

	var persisted int64
	if err := db.Model(&model.UserRolePermission{}).Where("role_id = ? AND permission_id = ?", "member", "CASE:WRITE").Count(&persisted).Error; err != nil {
		t.Fatalf("count persisted: %v", err)
	}
	if persisted != 1 {
		t.Fatalf("permission CASE:WRITE not persisted for role member (rows=%d, update=%s)", persisted, w.Body.String())
	}
}

