func TestOrganizationList_MemberCountIsRealAndTotalPagesPresent(t *testing.T) {
	db := setupDBOrgList(t)
	if err := db.Exec("DELETE FROM organization").Error; err != nil {
		t.Fatalf("clean organization: %v", err)
	}
	if err := db.Exec("DELETE FROM user_role_relation").Error; err != nil {
		t.Fatalf("clean relation: %v", err)
	}

	r := router.SetupRouter()
	post := func(path string) *httptest.ResponseRecorder {
		req := httptest.NewRequest(http.MethodPost, path, strings.NewReader(`{"current":1,"pageSize":10}`))
		req.Header.Set("Content-Type", "application/json")
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		return w
	}

	empty := post("/system/organization/list")
	if !strings.Contains(empty.Body.String(), `"totalPages"`) {
		t.Fatalf("total=0 response omits totalPages key (omitempty drops 0): %s", empty.Body.String())
	}

	if err := db.Create(&model.Organization{ID: "o1", Name: "Org One", Enable: model.BitBool(true), Deleted: model.BitBool(false), CreatedAt: 1700000000000}).Error; err != nil {
		t.Fatalf("seed organization: %v", err)
	}
	for _, uid := range []string{"u1", "u2", "u3"} {
		if err := db.Create(&model.UserRoleRelation{ID: "rel-" + uid, UserID: uid, RoleID: "org_admin", SourceID: "o1", CreatedAt: 1700000000000}).Error; err != nil {
			t.Fatalf("seed relation %s: %v", uid, err)
		}
	}

	var got struct {
		Code int `json:"code"`
		Data struct {
			List []struct {
				ID          string `json:"id"`
				MemberCount int    `json:"memberCount"`
			} `json:"list"`
			Total      int64 `json:"total"`
			TotalPages int64 `json:"totalPages"`
		} `json:"data"`
	}
	if err := json.Unmarshal(post("/system/organization/list").Body.Bytes(), &got); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if len(got.Data.List) != 1 {
		t.Fatalf("want 1 organization row, got %+v", got.Data.List)
	}
	if got.Data.List[0].MemberCount != 3 {
		t.Fatalf("memberCount is not aggregated from user_role_relation: got %d, want 3", got.Data.List[0].MemberCount)
	}
	if got.Data.TotalPages != 1 {
		t.Fatalf("totalPages wrong for total=1 pageSize=10: got %d, want 1", got.Data.TotalPages)
	}
}

