func TestSystemOrgAdd_SameMillisecondMustNotCollide(t *testing.T) {
	db := setupDBOrgAdd(t)
	if err := db.Exec("DELETE FROM organization").Error; err != nil {
		t.Fatalf("clean organization: %v", err)
	}

	r := router.SetupRouter()
	ids := make(map[string]bool, 2)
	for i := 0; i < 2; i++ {
		req := httptest.NewRequest(http.MethodPost, "/system/organization/add", strings.NewReader(`{"name":"DupOrg"}`))
		req.Header.Set("Content-Type", "application/json")
