			t.Fatalf("unmarshal: %v body=%s", err, w.Body.String())
		}
		if got.Code != 200 {
			t.Fatalf("add #%d failed: %s", i, w.Body.String())
		}
		ids[got.Data.ID] = true
	}

	var rows int64
	if err := db.Model(&model.Organization{}).Where("name = ?", "DupOrg").Count(&rows).Error; err != nil {
		t.Fatalf("count organization: %v", err)
	}
	if int64(len(ids)) != rows || rows != 2 {
		t.Fatalf("two successful adds produced %d row(s) with %d distinct id(s): UnixMilli 主键冲突 + Create error 被忽略", rows, len(ids))
	}
}

