func TestRecordAuditLog_MustNotTrustUserIDHeader(t *testing.T) {
	db := setupDBAudit(t)
	if err := db.Exec("DELETE FROM operation_log").Error; err != nil {
		t.Fatalf("clean log: %v", err)
	}

	r := router.SetupRouter()
	req := httptest.NewRequest(http.MethodPost, "/system/organization/add", strings.NewReader(`{"name":"AuditProbe"}`))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-User-Id", "attacker")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)

	var n int64
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		if err := db.Model(&model.OperationLog{}).Count(&n).Error; err != nil {
			t.Fatalf("count log: %v", err)
		}
		if n > 0 {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	if n == 0 {
		t.Fatalf("audit log not written within 2s (RecordAuditLog 在 goroutine 内写库，测试必须轮询)")
	}

	var rec model.OperationLog
	if err := db.Order("id DESC").First(&rec).Error; err != nil {
		t.Fatalf("read newest log: %v", err)
	}
	if rec.CreateUser == "attacker" {
		t.Fatalf("audit actor spoofable via unauthenticated X-User-Id header: create_user=%q content=%q", rec.CreateUser, rec.Content)
	}
	if rec.Module != "SYSTEM" || rec.OrganizationID != "SYSTEM" || rec.ProjectID != "SYSTEM" {
		t.Fatalf("module=SYSTEM 的审计未打 SYSTEM 标记: module=%q org=%q project=%q", rec.Module, rec.OrganizationID, rec.ProjectID)
	}
}

